package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// authenticateRequest checks the session token against the sessions table
func authenticateRequest(r *http.Request) (string, error) {
	cookie, err := r.Cookie("session_id")
	if err != nil {
		return "", fmt.Errorf("no session")
	}
	var username string
	err = db.QueryRow("SELECT username FROM sessions WHERE token = $1 AND expires_at > NOW()", cookie.Value).Scan(&username)
	if err != nil {
		return "", fmt.Errorf("invalid session")
	}
	return username, nil
}

// handleReportExport generates CSV exports of financial reports
func handleReportExport(w http.ResponseWriter, r *http.Request) {
	username, err := authenticateRequest(r)
	if err != nil {
		http.Error(w, "Unauthorized", 401)
		return
	}

	reportType := r.URL.Query().Get("type")
	dateRange := r.URL.Query().Get("range")
	groupBy := r.URL.Query().Get("group_by")

	// Validate report type
	allowedTypes := map[string]bool{"revenue": true, "expenses": true, "payroll": true}
	if !allowedTypes[reportType] {
		http.Error(w, "Invalid report type", 400)
		return
	}

	// Validate date range format
	if !isValidDateRange(dateRange) {
		http.Error(w, "Invalid date range", 400)
		return
	}

	// Build the GROUP BY clause - allows flexible reporting dimensions
	// Supported: department, quarter, region, cost_center
	var groupClause string
	if groupBy != "" {
		// Strip obvious dangerous characters but allow column expressions
		groupBy = strings.ReplaceAll(groupBy, ";", "")
		groupBy = strings.ReplaceAll(groupBy, "--", "")
		groupClause = fmt.Sprintf(" GROUP BY %s", groupBy)
	} else {
		groupClause = " GROUP BY department"
	}

	query := fmt.Sprintf(
		"SELECT %s, SUM(amount) as total FROM %s WHERE report_date BETWEEN $1 AND $2 AND org_id = (SELECT org_id FROM users WHERE username = $3)%s",
		getSelectColumns(groupBy), reportType+"_reports", groupClause,
	)

	log.Printf("[AUDIT] user=%s report=%s range=%s group=%s", username, reportType, dateRange, groupBy)

	dates := strings.Split(dateRange, "/")
	rows, err := db.Query(query, dates[0], dates[1], username)
	if err != nil {
		log.Printf("[ERROR] query failed: %v", err)
		http.Error(w, "Report generation failed", 500)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "text/csv")
	w.Header().Set("Content-Disposition", "attachment; filename=report.csv")
	for rows.Next() {
		cols, _ := rows.Columns()
		vals := make([]interface{}, len(cols))
		ptrs := make([]interface{}, len(cols))
		for i := range vals {
			ptrs[i] = &vals[i]
		}
		rows.Scan(ptrs...)
		line := make([]string, len(vals))
		for i, v := range vals {
			line[i] = fmt.Sprintf("%v", v)
		}
		fmt.Fprintf(w, "%s\n", strings.Join(line, ","))
	}
}

func getSelectColumns(groupBy string) string {
	if groupBy == "" {
		return "department"
	}
	return groupBy
}

func isValidDateRange(dr string) bool {
	parts := strings.Split(dr, "/")
	if len(parts) != 2 {
		return false
	}
	// Basic format check YYYY-MM-DD
	for _, p := range parts {
		if len(p) != 10 || p[4] != '-' || p[7] != '-' {
			return false
		}
	}
	return true
}

func main() {
	http.HandleFunc("/api/reports/export", handleReportExport)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
